-- Generated by `make contracts` from contracts/cdc_nhsn_ar_hai.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'cdc_nhsn_ar_hai') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "source" AS "source",
  CASE WHEN CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("year"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('year: a value has a fraction, so it isn''t a whole count; check the contract') END AS "year",
  "geography" AS "geography",
  "event_type" AS "event_type",
  "phenotype" AS "phenotype",
  "age_category" AS "age_category",
  "sex" AS "sex",
  "teaching_hospital" AS "teaching_hospital",
  "hospital_size" AS "hospital_size",
  "facility" AS "facility",
  "procedure" AS "procedure",
  "location" AS "location",
  CASE WHEN CAST(NULLIF(trim("isolates_tested"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("isolates_tested"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("isolates_tested"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("isolates_tested"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('isolates_tested: a value has a fraction, so it isn''t a whole count; check the contract') END AS "isolates_tested",
  CASE WHEN CAST(NULLIF(trim("resistant_isolates"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("resistant_isolates"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("resistant_isolates"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("resistant_isolates"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('resistant_isolates: a value has a fraction, so it isn''t a whole count; check the contract') END AS "resistant_isolates",
  CAST(NULLIF(trim("percent_resistant"), '') AS DOUBLE) AS "percent_resistant",
  CASE lower(trim("suppressed")) WHEN 'true' THEN true WHEN 'false' THEN false ELSE NULL END AS "suppressed",
  "display_tested" AS "display_tested",
  CAST(NULLIF(trim("lower_confidence_interval"), '') AS DOUBLE) AS "lower_confidence_interval",
  CAST(NULLIF(trim("upper_confidence_interval"), '') AS DOUBLE) AS "upper_confidence_interval"
from latest
